# Create demo3 point map, search output-shape and its 180 rotation occurrences
pts={(2,11),(2,13),(4,1),(4,8),(5,11),(6,7),(6,8),(7,8),(7,9),(7,13),(8,1),(8,7),(8,8),(10,8),(11,6),(11,11),(13,1),(13,6)}
out={(0,0),(0,2),(1,0),(1,1),(1,2),(2,1)}
def findshape(shape):
  res=[]
  for r in range(15):
   for c in range(15):
    if all((r+dr,c+dc) in pts for dr,dc in shape):res.append((r,c))
  return res
print(findshape(out),findshape({(2-r,2-c) for r,c in out}))

upper={(5,5),(5,7),(6,2),(6,4),(6,6),(6,11),(7,6),(9,2),(9,6)}
lower={(1,6),(1,9),(4,6),(5,9),(6,2),(6,4),(6,11),(7,6),(8,2),(8,6),(8,9),(9,8),(9,10)}
def comps8(pts):
 rem=set(pts); out=[]
 while rem:
  stack=[rem.pop()]; comp=set(stack)
  while stack:
   r,c=stack.pop()
   for p in list(rem):
    if max(abs(p[0]-r),abs(p[1]-c))==1:
     rem.remove(p);comp.add(p);stack.append(p)
  out.append(comp)
 return out
def norm(s):
 mr=min(r for r,c in s); mc=min(c for r,c in s)
 return frozenset((r-mr,c-mc) for r,c in s)
for name,pts in [('up',upper),('lo',lower)]:
 print(name,[(len(c),sorted(c), norm(c)) for c in comps8(pts)])

# max translated common shape among all dots in panel pairs
