print(sorted(best,reverse=True)[:15])

# symmetry normalized transforms and best correspondences of subsets between upper/lower
from itertools import product
transforms=[lambda r,c:(r,c),lambda r,c:(r,-c),lambda r,c:(-r,c),lambda r,c:(-r,-c),lambda r,c:(c,r),lambda r,c:(c,-r),lambda r,c:(-c,r),lambda r,c:(-c,-r)]
for ti,f in enumerate(transforms):
 trans={f(r,c) for r,c in upper}
 bestm=[]
 for dr in range(-20,21):
  for dc in range(-20,21):
   # transform original up, then add translation
   matched=[p for p in trans if (p[0]+dr,p[1]+dc) in lower]
   if len(matched)>len(bestm):bestm=[matched,dr,dc]
 print(ti,len(bestm[0]),bestm[1:])

# enumerate translated 3point subset matches, record geometry / source positions
import itertools, collections
matches=[]
for su in itertools.combinations(upper,3):
 for sl in itertools.combinations(lower,3):
  du=sorted((r-min(x for x,y in su),c-min(y for x,y in su)) for r,c in su)
  dl=sorted((r-min(x for x,y in sl),c-min(y for x,y in sl)) for r,c in sl)
  if du==dl:
   matches.append((tuple(du),tuple(sorted(su)),tuple(sorted(sl))))
byshape=collections.defaultdict(list)
for m in matches: byshape[m[0]].append(m[1:])
[(shape,len(arr),arr[:5]) for shape,arr in byshape.items() if len(arr)>1][:20]

