# helper all affine D4 transforms preserving lattice
transforms2=[lambda r,c:(r,c),lambda r,c:(r,-c),lambda r,c:(-r,c),lambda r,c:(-r,-c),lambda r,c:(c,r),lambda r,c:(c,-r),lambda r,c:(-c,r),lambda r,c:(-c,-r)]
def best_match(a,b):
 vals=[]
 for i,f in enumerate(transforms2):
  at={f(r,c) for r,c in a}
  for dr in range(-10,11):
